package mx.com.mesaregia.pagos.application.service.impl;
import mx.com.mesaregia.pagos.api.response.*; import mx.com.mesaregia.pagos.exception.ResourceNotFoundException; import mx.com.mesaregia.pagos.repository.*; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class PagoQuerySupport {private final PagoRepository pagos;private final AplicacionPagoRepository apps;private final CuentaCobroServiceImpl cuentas;public PagoQuerySupport(PagoRepository p,AplicacionPagoRepository a,CuentaCobroServiceImpl c){pagos=p;apps=a;cuentas=c;}@Transactional(readOnly=true) public PagoRegistroResponse pago(Long id,boolean idem,boolean ev){var p=pagos.findById(id).orElseThrow(()->new ResourceNotFoundException("Pago no encontrado"));var a=apps.findFirstByPagoId(id).orElseThrow(()->new ResourceNotFoundException("Aplicación de pago no encontrada"));return new PagoRegistroResponse(p.getId(),p.getFolio(),idem,ev,false,cuentas.obtenerPorId(a.getCuentaCobro().getId()));}}
